package config

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// Config is the complete runtime configuration for vps-watchdog.
//
// The MVP intentionally supports a small YAML subset instead of pulling in a
// YAML dependency. Supported syntax is the simple mapping structure generated by
// configs/config.example.yaml and packaging/install.sh.
type Config struct {
	HostID   string
	Telegram TelegramConfig
	Login    LoginConfig
	Sudo     SudoConfig
	Load     LoadConfig
}

type TelegramConfig struct {
	TokenFile  string
	ChatIDFile string
}

type LoginConfig struct {
	Enabled bool
}

type SudoConfig struct {
	Enabled bool
}

type LoadConfig struct {
	Enabled             bool
	SampleIntervalSec   int
	CooldownSec         int
	CPUBusyPercent      float64
	CPUDurationSec      int
	MemAvailablePercent float64
	MemDurationSec      int
	PSIIOSomeAvg60      float64
	IODurationSec       int
}

func Default() Config {
	host, _ := os.Hostname()
	if strings.TrimSpace(host) == "" {
		host = "unknown"
	}
	return Config{
		HostID: host,
		Telegram: TelegramConfig{
			TokenFile:  "/etc/vps-watchdog/telegram.token",
			ChatIDFile: "/etc/vps-watchdog/telegram.chat_id",
		},
		Login: LoginConfig{Enabled: true},
		Sudo:  SudoConfig{Enabled: true},
		Load: LoadConfig{
			Enabled:             true,
			SampleIntervalSec:   15,
			CooldownSec:         900,
			CPUBusyPercent:      90,
			CPUDurationSec:      180,
			MemAvailablePercent: 10,
			MemDurationSec:      180,
			PSIIOSomeAvg60:      20,
			IODurationSec:       180,
		},
	}
}

func LoadFile(path string) (Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config %s: %w", path, err)
	}
	return Parse(data)
}

func Parse(data []byte) (Config, error) {
	cfg := Default()
	values, err := parseSimpleYAML(data)
	if err != nil {
		return Config{}, err
	}

	for key, raw := range values {
		switch key {
		case "host_id":
			cfg.HostID = parseString(raw)
		case "telegram.token_file":
			cfg.Telegram.TokenFile = parseString(raw)
		case "telegram.chat_id_file":
			cfg.Telegram.ChatIDFile = parseString(raw)
		case "login.enabled":
			cfg.Login.Enabled, err = parseBool(key, raw)
		case "sudo.enabled":
			cfg.Sudo.Enabled, err = parseBool(key, raw)
		case "load.enabled":
			cfg.Load.Enabled, err = parseBool(key, raw)
		case "load.sample_interval_sec":
			cfg.Load.SampleIntervalSec, err = parseInt(key, raw)
		case "load.cooldown_sec":
			cfg.Load.CooldownSec, err = parseInt(key, raw)
		case "load.cpu_busy_percent":
			cfg.Load.CPUBusyPercent, err = parseFloat(key, raw)
		case "load.cpu_duration_sec":
			cfg.Load.CPUDurationSec, err = parseInt(key, raw)
		case "load.mem_available_percent":
			cfg.Load.MemAvailablePercent, err = parseFloat(key, raw)
		case "load.mem_duration_sec":
			cfg.Load.MemDurationSec, err = parseInt(key, raw)
		case "load.psi_io_some_avg60":
			cfg.Load.PSIIOSomeAvg60, err = parseFloat(key, raw)
		case "load.io_duration_sec":
			cfg.Load.IODurationSec, err = parseInt(key, raw)
		default:
			return Config{}, fmt.Errorf("unknown config key %q", key)
		}
		if err != nil {
			return Config{}, err
		}
	}

	if err := cfg.Validate(); err != nil {
		return Config{}, err
	}
	return cfg, nil
}

func (c Config) Validate() error {
	var errs []string
	if strings.TrimSpace(c.HostID) == "" {
		errs = append(errs, "host_id must not be empty")
	}
	if strings.TrimSpace(c.Telegram.TokenFile) == "" {
		errs = append(errs, "telegram.token_file must not be empty")
	}
	if strings.TrimSpace(c.Telegram.ChatIDFile) == "" {
		errs = append(errs, "telegram.chat_id_file must not be empty")
	}
	if c.Load.SampleIntervalSec <= 0 {
		errs = append(errs, "load.sample_interval_sec must be > 0")
	}
	if c.Load.CooldownSec < 0 {
		errs = append(errs, "load.cooldown_sec must be >= 0")
	}
	if c.Load.CPUBusyPercent <= 0 || c.Load.CPUBusyPercent > 100 {
		errs = append(errs, "load.cpu_busy_percent must be in (0, 100]")
	}
	if c.Load.CPUDurationSec <= 0 {
		errs = append(errs, "load.cpu_duration_sec must be > 0")
	}
	if c.Load.MemAvailablePercent <= 0 || c.Load.MemAvailablePercent > 100 {
		errs = append(errs, "load.mem_available_percent must be in (0, 100]")
	}
	if c.Load.MemDurationSec <= 0 {
		errs = append(errs, "load.mem_duration_sec must be > 0")
	}
	if c.Load.PSIIOSomeAvg60 < 0 || c.Load.PSIIOSomeAvg60 > 100 {
		errs = append(errs, "load.psi_io_some_avg60 must be in [0, 100]")
	}
	if c.Load.IODurationSec <= 0 {
		errs = append(errs, "load.io_duration_sec must be > 0")
	}
	if len(errs) > 0 {
		return errors.New(strings.Join(errs, "; "))
	}
	return nil
}

func parseSimpleYAML(data []byte) (map[string]string, error) {
	values := make(map[string]string)
	parents := map[int][]string{}
	scanner := bufio.NewScanner(strings.NewReader(string(data)))
	lineNo := 0

	for scanner.Scan() {
		lineNo++
		line := stripComment(scanner.Text())
		if strings.TrimSpace(line) == "" {
			continue
		}
		indent := countLeadingSpaces(line)
		if indent%2 != 0 {
			return nil, fmt.Errorf("config line %d: indentation must use multiples of two spaces", lineNo)
		}
		trimmed := strings.TrimSpace(line)
		idx := strings.Index(trimmed, ":")
		if idx <= 0 {
			return nil, fmt.Errorf("config line %d: expected key: value", lineNo)
		}
		key := strings.TrimSpace(trimmed[:idx])
		val := strings.TrimSpace(trimmed[idx+1:])
		if key == "" {
			return nil, fmt.Errorf("config line %d: empty key", lineNo)
		}

		var parent []string
		if indent > 0 {
			var ok bool
			parent, ok = parents[indent-2]
			if !ok {
				return nil, fmt.Errorf("config line %d: missing parent for %q", lineNo, key)
			}
		}
		path := append(append([]string{}, parent...), key)
		parents[indent] = path
		for existing := range parents {
			if existing > indent {
				delete(parents, existing)
			}
		}
		if val == "" {
			continue
		}
		values[strings.Join(path, ".")] = val
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return values, nil
}

func stripComment(line string) string {
	inSingle := false
	inDouble := false
	for i, r := range line {
		switch r {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble {
				return line[:i]
			}
		}
	}
	return line
}

func countLeadingSpaces(line string) int {
	count := 0
	for _, r := range line {
		if r != ' ' {
			break
		}
		count++
	}
	return count
}

func parseString(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

func parseBool(key, raw string) (bool, error) {
	v, err := strconv.ParseBool(parseString(raw))
	if err != nil {
		return false, fmt.Errorf("config %s: expected bool: %w", key, err)
	}
	return v, nil
}

func parseInt(key, raw string) (int, error) {
	v, err := strconv.Atoi(parseString(raw))
	if err != nil {
		return 0, fmt.Errorf("config %s: expected integer: %w", key, err)
	}
	return v, nil
}

func parseFloat(key, raw string) (float64, error) {
	v, err := strconv.ParseFloat(parseString(raw), 64)
	if err != nil {
		return 0, fmt.Errorf("config %s: expected number: %w", key, err)
	}
	return v, nil
}
